// tslabs holds the chunks the typed values of a parse are allocated from.
type tslabs struct {
	tAttribute      []Attribute
	tBool           []Bool
	tBottom         []Bottom
	tFloat          []Float
	tIdent          []Ident
	tInt            []Int
	tNull           []Null
	tString         []String
	tAlias          []Alias
	tBinaryExpr     []BinaryExpr
	tCallExpr       []CallExpr
	tComprehension  []Comprehension
	tEllipsis       []Ellipsis
	tEmbedDecl      []EmbedDecl
	tFallbackClause []FallbackClause
	tField          []Field
	tFile           []File
	tForClause      []ForClause
	tIfClause       []IfClause
	tImportDecl     []ImportDecl
	tImportSpec     []ImportSpec
	tIndexExpr      []IndexExpr
	tInterpolation  []Interpolation
	tLetClause      []LetClause
	tListLit        []ListLit
	tPackage        []Package
	tParenExpr      []ParenExpr
	tPostfixAlias   []PostfixAlias
	tPostfixExpr    []PostfixExpr
	tSelectorExpr   []SelectorExpr
	tSliceExpr      []SliceExpr
	tStructLit      []StructLit
	tTryClause      []TryClause
	tUnaryExpr      []UnaryExpr
	tl0Chunk        []Expr
	tl1Chunk        []Clause
	tl2Chunk        []*Attribute
	tl3Chunk        []Decl
	tl4Chunk        []*ImportSpec
}

// ParseAST parses the input like Parse and returns the result as typed values. If the parse recovered
// from errors, the result is returned together with SyntaxErrors; an Error node where a struct or
// terminal type is expected becomes nil.
// It builds the values directly, without the nodes Parse returns.
func ParseAST(input string, unit ...Unit) (*File, error) {
	a := &tslabs{}
	return tparse(trules[0], input, unit, a, func(v any) *File { return tAs[*File](v) })
}

